import { BrowserRouter, Routes, Route } from "react-router-dom";

import LoginScreen from "../screens/LoginScreens";
import HomeScreen from "../screens/HomeScreens";
import ProductScreen from "../screens/ProductScreens";
import ProductDetailsScreens from "../screens/ProductDetailsScreens";
import CartScreens from "../screens/CartScreens";

export default function AppNavigator() {
  return (
    <BrowserRouter basename="/watch">
      <Routes>
        <Route path="/" element={<LoginScreen />} />
        <Route path="/home" element={<HomeScreen />} />
        <Route path="/products" element={<ProductScreen />} />
        <Route path="/products/:id" element={<ProductDetailsScreens />} />
        <Route path="/cart" element={<CartScreens />} />
      </Routes>
    </BrowserRouter>
  );
}
