import React, { useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { toast } from "react-toastify";
import { motion } from "framer-motion";

import Header from "../components/Header";
import { Box, Typography, Button, Grid } from "@mui/material";

export default function HomeScreen() {
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    if (location.state?.fromLogin) {
      toast.success("Welcome to Flipkart 🎉", {
        toastId: "home-login",
      });
    }
  }, [location.state]);

  return (
    <>
      <Header />

      {/* HERO SECTION */}
      <Box
        sx={{
          minHeight: "90vh",
          background:
            "linear-gradient(135deg, #2874f0 0%, #5c9ded 100%)",
          color: "#fff",
          display: "flex",
          alignItems: "center",
          px: { xs: 3, md: 10 },
        }}
      >
        <Grid container spacing={4} alignItems="center">
          {/* LEFT CONTENT */}
          <Grid item xs={12} md={6}>
            <motion.div
              initial={{ opacity: 0, y: 50 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8 }}
            >
              <Typography variant="h2" fontWeight="bold" gutterBottom>
                Best Online Shopping Experience
              </Typography>

              <Typography variant="h6" sx={{ opacity: 0.9, mb: 3 }}>
                Shop the latest products at unbeatable prices.
              </Typography>

              {/* ✅ ONLY THIS BUTTON NAVIGATES */}
              <Button
                variant="contained"
                size="large"
                sx={{
                  bgcolor: "#ff9f00",
                  color: "#000",
                  px: 4,
                  py: 1.5,
                  fontWeight: "bold",
                  "&:hover": { bgcolor: "#ffc107" },
                }}
                onClick={() => navigate("/products")}
              >
                Shop Now
              </Button>
            </motion.div>
          </Grid>

          {/* RIGHT IMAGE (NO CLICK) */}
          <Grid item xs={12} md={6}>
            <motion.img
              src="https://cdn-icons-png.flaticon.com/512/263/263142.png"
              alt="shopping"
              style={{ width: "100%", maxWidth: 450, pointerEvents: "none" }}
              initial={{ opacity: 0, x: 100 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 1 }}
            />
          </Grid>
        </Grid>
      </Box>
    </>
  );
}
